package com.kai.automusic;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.widget.*;
public final class PermissionSetup {
 final Activity a; final SharedPreferences p; AlertDialog dialog; LinearLayout rows;
 PermissionSetup(Activity a){this.a=a;p=a.getSharedPreferences("music",0);}
 boolean granted(String s){return a.checkSelfPermission(s)==PackageManager.PERMISSION_GRANTED;}
 Uri pkg(){return Uri.parse("package:"+a.getPackageName());}
 void open(String action,boolean packageUri){try{Intent i=new Intent(action);if(packageUri)i.setData(pkg());a.startActivity(i);}catch(Exception e){try{a.startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,pkg()));}catch(Exception ignored){}}}
 void show(){if(dialog!=null&&dialog.isShowing()){refresh();return;}ScrollView s=new ScrollView(a);rows=new LinearLayout(a);rows.setOrientation(1);int d=(int)(16*a.getResources().getDisplayMetrics().density);rows.setPadding(d,d,d,d);s.addView(rows);dialog=new AlertDialog.Builder(a).setTitle("Permission Setup").setView(s).setPositiveButton("เสร็จสิ้น",(x,y)->p.edit().putBoolean("permissionSetupSeen",true).apply()).setNegativeButton("ภายหลัง",(x,y)->p.edit().putBoolean("permissionSetupSeen",true).apply()).create();dialog.show();refresh();}
 void row(String title,String desc,boolean ok,Runnable action){TextView t=new TextView(a);t.setText(title+" • "+(ok?"อนุญาตแล้ว":"ยังไม่ได้อนุญาต")+"\n"+desc);t.setTextColor(ok?0xff80cbc4:0xffffcc80);rows.addView(t);Button b=new Button(a);b.setText(ok?"ตรวจสอบ":"อนุญาต");b.setOnClickListener(v->action.run());rows.addView(b);}
 void info(String text,Runnable action){TextView t=new TextView(a);t.setText(text);rows.addView(t);if(action!=null){Button b=new Button(a);b.setText("เปิดการตั้งค่า");b.setOnClickListener(v->action.run());rows.addView(b);}}
 void refresh(){if(dialog==null||!dialog.isShowing())return;rows.removeAllViews();row("ไมโครโฟน","ใช้ Visualizer สำหรับคลื่นเสียง ไม่บันทึกเสียงพูด",granted(android.Manifest.permission.RECORD_AUDIO),()->{if(granted(android.Manifest.permission.RECORD_AUDIO))open(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,true);else a.requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},81);});row("แสดงทับแอปอื่น","สิทธิ์สำหรับการเปิดหน้าจอจากเบื้องหลังและหน้าต่างลอยในอนาคต",Settings.canDrawOverlays(a),()->open(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,true));PowerManager pm=(PowerManager)a.getSystemService(Context.POWER_SERVICE);row("แบตเตอรี่","ลดการจำกัดบริการเล่นเพลงเบื้องหลัง",pm.isIgnoringBatteryOptimizations(a.getPackageName()),()->open(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS,false));if(Build.VERSION.SDK_INT>=31){AlarmManager am=(AlarmManager)a.getSystemService(Context.ALARM_SERVICE);row("ตั้งเวลาที่แม่นยำ","เริ่มเพลงตามตาราง",am.canScheduleExactAlarms(),()->open(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,true));}row("การแจ้งเตือน","แสดงสถานะบริการเล่นเพลง",a.getSystemService(NotificationManager.class).areNotificationsEnabled(),()->open(Settings.ACTION_APP_NOTIFICATION_SETTINGS,false));info("ไฟล์เพลง / MP4: อนุญาตเมื่อเลือกไฟล์หรือโฟลเดอร์ ไม่ต้องเข้าถึงไฟล์ทั้งหมด",null);info("Auto Start / Background: ต้องตรวจสอบเองตามรุ่นโทรศัพท์ ไม่สามารถอ่านสถานะสิทธิ์เฉพาะผู้ผลิตได้",()->open(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,true));info("Boot receiver / Foreground service / Wake lock: ประกาศในระบบแล้ว ไม่ต้องกดอนุญาต",null);}
}